# picoride sample: square wave sound from a project mrbgem (mrbgems/sound)
#
# Wiring: GPIO4 -- passive piezo buzzer -- 330 ohm resistor -- GND
#
# Works with both PicoRuby and FemtoRuby, on ESP32 and Raspberry Pi Pico,
# without patching R2P2: the tone is generated by the gem's own C code.
require 'tiny_sound'

sound = TinySound.new(4)

# A single tone: 440 Hz (A4) for half a second
sound.tone(440, 500)
sound.rest(300)

# Note names
sound.note("C5", 200)
sound.note("E5", 200)
sound.note("G5", 400)
sound.rest(500)

# A scale and a melody in MML
#   C D E F G A B: notes, R: rest, O: octave, < >: octave down/up,
#   L: default length, T: tempo, numbers: length, . : dotted
sound.play("T180 O4 L8 CDEFGAB>C")
sound.rest(500)
